"""
Brain Wiki — Karpathy式 パーソナルナレッジベース
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

設計思想 (Karpathy Principles):
1. Raw data is source code — 生データは不変のソース
2. LLM is the compiler — LLMが知識を「コンパイル」してWikiを生成
3. Cognitive Core — 推論エンジン(LLM) と記憶(Wiki) を分離
4. Active maintenance — 定期的にLintして矛盾検出・補完・再構造化
5. Markdown is truth — 人間が読める・編集できる・Git管理できる

ディレクトリ構造:
  brain/
  ├── raw/              # 生データ（会話ログ、メモ、クリップ）
  │   ├── conversations/
  │   ├── notes/
  │   └── clips/
  ├── wiki/             # コンパイル済みの「あなた」
  │   ├── index.md      # 全体マップ
  │   ├── identity.md   # 価値観・信念・性格
  │   ├── style.md      # 文体・口癖・コミュニケーション特性
  │   ├── thinking.md   # 判断パターン・意思決定の傾向
  │   ├── knowledge/    # 専門知識（トピック別 .md）
  │   ├── people/       # 人間関係マップ
  │   ├── projects/     # 進行中プロジェクト
  │   └── decisions/    # 重要な意思決定ログ
  └── schema/           # コンパイルルール
      └── compile.md    # LLMへのコンパイル指示
"""

from __future__ import annotations  # ★2026-05-23: Python 3.9 でも `str | None` 等 PEP 604 type hint を parse 通すため

import asyncio  # ★2026-05-26 fix (= revert された e4c50fa の漏れ修正): parallel_load で asyncio.gather/to_thread 使用
import os
