import hashlib
from collections import OrderedDict
from datetime import datetime, date, timezone, timedelta

# ★2026-05-24 timezone bug fix (海山「売上常に fail」緊急指示):
# docker container TZ が UTC のまま、JST 早朝 (= 0-9 時) で date.today() が UTC 前日を返す。
# 売上 query で「昨日」が 1 日古いデータを参照 → 期待値と乖離 → sales_accuracy FAIL 連発。
# 修正: JST 明示で「今日 = JST 0:00 〜 24:00」と確定。
JST = timezone(timedelta(hours=9))


def _today_jst():
    """JST date を明示返却 (= docker TZ ミスに依存しない)。"""
    return datetime.now(JST).date()


# ★2026-07-12 QA 反映: 自社名の綴り事故を決定論で矯正 (GPT-5.4 が「OWDAYS」= N 抜け /
# 「OWNDAY」= S 抜け を稀に生成 → CEO クローンが自社名を間違える信頼毀損)。全 clone 応答に適用。
def _canonicalize_brand(t: str) -> str:
    if not t:
        return t
    t = t.replace("OWDAYS", "OWNDAYS").replace("OWNADYS", "OWNDAYS")  # N 抜け / 綴り転倒
    t = re.sub(r"OWNDAY(?!S)", "OWNDAYS", t)   # S 抜け (OWNDAYS の途中では発火しない)
    return t
from pathlib import Path
from typing import Optional, List, Dict, Any
import httpx
import logging

